  };
}

export interface CreateMenuItemData {
  schoolId: string;
  name: string;
  description?: string;
  price: number;
  category: string;
  imageUrl?: string;
  nutritionalInfo?: {
    calories: number;
    protein: number;
    carbs: number;
    fat: number;
    fiber: number;
    sodium: number;
  };
  allergens?: string[];
  dietaryRestrictions?: string[];
  preparationTime?: number; // in minutes
  available: boolean;
  maxDailyQuantity?: number;
  tags?: string[];
}

export interface UpdateMenuItemData extends Partial<CreateMenuItemData> {
  id: string;
}

export interface MenuPlanData {
