/**
 * Notification Service
 * Business logic for notification management
 */

import { PrismaClient, Notification } from '@prisma/client';

export interface NotificationFilters {
  userId?: string;
  type?: string;
  status?: string;
  isRead?: boolean;
}

export interface CreateNotificationData {
  userId: string;
  type: string;
  title: string;
  message: string;
  data?: any;
  scheduledFor?: Date;
}

// Enums
export const NotificationStatus = {
  PENDING: 'pending',
  SENT: 'sent',
  DELIVERED: 'delivered',
  READ: 'read',
  FAILED: 'failed',
  EXPIRED: 'expired',
} as const;

export type NotificationStatus = (typeof NotificationStatus)[keyof typeof NotificationStatus];

export const NotificationPriority = {
  LOW: 'low',
  NORMAL: 'normal',
  HIGH: 'high',
  URGENT: 'urgent',
} as const;

export type NotificationPriority = (typeof NotificationPriority)[keyof typeof NotificationPriority];

export type NotificationChannel = 'push' | 'email' | 'sms' | 'whatsapp' | 'in_app' | 'socket';

// Request/Response types
export interface NotificationRequest {
  templateId: string;
  recipientId: string;
  recipientType: 'parent' | 'student' | 'staff';
  channels?: NotificationChannel[];
  variables?: Record<string, any>;
  priority?: NotificationPriority;
  expiresAt?: Date;
}

export interface BulkNotificationRequest {
  templateId: string;
  recipients: Array<{
    recipientId: string;
    recipientType: 'parent' | 'student' | 'staff';
    variables: Record<string, any>;
  }>;
  channels?: NotificationChannel[];
  priority?: NotificationPriority;
}

export interface OrderConfirmationData {
  orderId: string;
  studentId: string;
  parentId: string;
  totalAmount: number;
  deliveryDate: Date;
}

export interface OrderStatusUpdateData {
  orderId: string;
  studentId: string;
  parentId: string;
  newStatus: string;
  message?: string;
}

export interface NotificationPreferences {
  channels: {
    push: boolean;
    email: boolean;
    sms: boolean;
    whatsapp: boolean;
    in_app: boolean;
    socket: boolean;
  };
  quietHours: {
    enabled: boolean;
    startTime: string;
    endTime: string;
    timezone: string;
  };
  frequency: {
    email: 'immediate' | 'daily' | 'weekly';
    push: 'immediate' | 'batched';
    sms: 'immediate' | 'urgent_only';
    whatsapp: 'immediate' | 'batched';
  };
  topics: {
    orderUpdates: boolean;
    paymentUpdates: boolean;
    systemAnnouncements: boolean;
    promotions: boolean;
  };
}

export interface NotificationAnalytics {
  totalSent: number;
  totalDelivered: number;
  totalRead: number;
  deliveryRate: number;
  readRate: number;
  channelStats: Record<
    NotificationChannel,
    {
      sent: number;
      delivered: number;
      read: number;
      failed: number;
    }
  >;
  templateStats: Record<
    string,
    {
      sent: number;
      delivered: number;
      read: number;
    }
  >;
  timeSeries: Array<{
    date: string;
    sent: number;
    delivered: number;
    read: number;
  }>;
}

export class NotificationService {
  private static instance: NotificationService;
  private prisma: PrismaClient;

  private constructor() {
    this.prisma = new PrismaClient();
  }

  public static getInstance(): NotificationService {
    if (!NotificationService.instance) {
      NotificationService.instance = new NotificationService();
    }
    return NotificationService.instance;
  }

  async findById(id: string): Promise<Notification | null> {
    return await this.prisma.notification.findUnique({
      where: { id },
    });
  }

  async findByUser(userId: string): Promise<Notification[]> {
    return await this.prisma.notification.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
    });
  }

  async findUnread(userId: string): Promise<Notification[]> {
    return await this.prisma.notification.findMany({
      where: {
        userId,
        readAt: null,
      },
      orderBy: { createdAt: 'desc' },
    });
  }

  async findAll(filters?: NotificationFilters): Promise<Notification[]> {
    const where: any = {};

    if (filters?.userId) {
      where.userId = filters.userId;
    }

    if (filters?.type) {
      where.type = filters.type;
    }

    if (filters?.status) {
      where.status = filters.status;
    }

    if (filters?.isRead !== undefined) {
      where.isRead = filters.isRead;
    }

    return await this.prisma.notification.findMany({
      where,
      orderBy: { createdAt: 'desc' },
    });
  }

  async create(data: CreateNotificationData): Promise<Notification> {
    return await this.prisma.notification.create({
      data: {
        userId: data.userId,
        type: data.type,
        title: data.title,
        message: data.message,
        data: data.data ? JSON.stringify(data.data) : null,
        scheduledFor: data.scheduledFor,
        status: 'pending',
        isRead: false,
      } as any,
    });
  }

  async markAsRead(id: string): Promise<Notification> {
    return await this.prisma.notification.update({
      where: { id },
      data: {
        readAt: new Date(),
        status: 'read',
      },
    });
